package main

import (
	"fmt"
	"os"
)

func main() {
	const name = "parcelhub"
	args := os.Args[1:]
	if len(args) > 0 && !(len(args) == 1 && (args[0] == "--help" || args[0] == "-h")) {
		fmt.Fprintln(os.Stderr, name+": unknown arguments; use --help")
		os.Exit(2)
	}
	fmt.Printf("%s\n\nUsage: go run . [--help]\n\n包裹配送与异常处理。当前仅提供帮助信息。\n", name)
}

