}

func TestCorruptFileRejected(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "ledger.json")

	cases := map[string]string{
		"非法JSON":   "{not json",
		"空文件":     "",
		"空白文件":    "   \n ",
		"缺少字段":   `{"version":1}`,
		"版本不支持":  `{"version":99,"parcels":{},"handoffs":{}}`,
		"包裹记录损坏": `{"version":1,"parcels":{"P001":null},"handoffs":{}}`,
		"交接引用丢失包裹": `{"version":1,"parcels":{},"handoffs":{"R1":{"request":"R1","from":"A","to":"B","parcels":["P9"],"time":"2026-10-05T09:00:00Z"}}}`,
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
				t.Fatal(err)
			}
			s, err := Open(path)
			if err == nil {
				t.Fatal("损坏文件必须被拒绝打开")
			}
			if !errors.Is(err, ErrCorrupt) {
				t.Fatalf("应返回 ErrCorrupt，得到 %v", err)
			}
			// 拒绝后即使内存对象存在，登记也不得覆盖损坏文件：
			if s != nil {
				if _, err := s.Register("PX", "站点A", tClock(2026, 10, 5, 9, 0)); err == nil {
					t.Fatal("损坏库不得继续写入")
				}
			}
			got, _ := os.ReadFile(path)
			if string(got) != content {
				t.Fatal("损坏文件不得被覆盖")
			}
		})
	}
}

func TestSaveFailureRollsBack(t *testing.T) {
