90	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
91	func (l *ledgerFile) validate() error {
92		for id, p := range l.Parcels {
93			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
94				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
95			}
96		}
97		for req, h := range l.Handoffs {
98			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
99				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
100			}
101			for _, id := range h.Parcels {
102				if _, ok := l.Parcels[id]; !ok {
103					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
104				}
105			}
106		}
107		return nil
108	}
