110	// Register 执行单件收件登记并将结果整体落盘。
111	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
112		if _, ok := s.data.Parcels[id]; ok {
113			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
114		}
115		p := &Parcel{
116			ID:         id,
117			Station:    station,
118			Status:     statusInStation,
119			Registered: now,
120			Trail: []Event{{
121				Op:      "收件",
122				Station: station,
123				Time:    now,
124			}},
125		}
126		s.data.Parcels[id] = p
127		if err := s.save(); err != nil {
128			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
129			return nil, err
130		}
131		return p, nil
132	}
133	
134	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
135	func (s *Store) Query(id string) (*Parcel, error) {
136		p, ok := s.data.Parcels[id]
137		if !ok {
138			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
139		}
140		return p, nil
141	}
