210	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
211	func sameSet(a, b []string) bool {
212		if len(a) != len(b) {
213			return false
214		}
215		x := append([]string(nil), a...)
216		y := append([]string(nil), b...)
217		sort.Strings(x)
218		sort.Strings(y)
219		for i := range x {
220			if x[i] != y[i] {
221				return false
222			}
223		}
224		return true
225	}
226	
227	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
228	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
229	func (s *Store) save() error {
230		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
231			return fmt.Errorf("保存数据文件失败: %w", err)
232		}
233		buf, err := json.MarshalIndent(s.data, "", "  ")
234		if err != nil {
235			return fmt.Errorf("保存数据文件失败: %w", err)
236		}
237		buf = append(buf, '\n')
238	
239		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
240		if err != nil {
241			return fmt.Errorf("保存数据文件失败: %w", err)
242		}
243		tmpName := tmp.Name()
244		cleanup := func() { _ = os.Remove(tmpName) }
245	
246		if _, err := tmp.Write(buf); err != nil {
247			_ = tmp.Close()
248			cleanup()
249			return fmt.Errorf("保存数据文件失败: %w", err)
250		}
251		if err := tmp.Sync(); err != nil {
252			_ = tmp.Close()
253			cleanup()
254			return fmt.Errorf("保存数据文件失败: %w", err)
255		}
256		if err := tmp.Close(); err != nil {
257			cleanup()
258			return fmt.Errorf("保存数据文件失败: %w", err)
259		}
260	
261		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
262		var check ledgerFile
263		if err := json.Unmarshal(buf, &check); err != nil {
264			cleanup()
265			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
266		}
267	
268		if err := os.Rename(tmpName, s.path); err != nil {
269			cleanup()
270			return fmt.Errorf("保存数据文件失败: %w", err)
271		}
272		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
273			_ = dir.Sync()
274			_ = dir.Close()
275		}
276		return nil
277	}
